/* One piece per question. Artwork is native SVG and scales to mobile screens. */
const PUZZLE_UNITS=[{id:'1',title:'臺灣探索島',subtitle:'第一單元 · 自然與先民',icon:'🌿'},{id:'2',title:'大航海港口',subtitle:'第二單元 · 航線與交流',icon:'⛵'}];
function puzzleUnit(q){const u=topics[q.topic].unit;if(u==='1'||u==='2')return u;if(u==='extra')return q.id<=202?'1':'2';return q.id<=213||[221,222,223].includes(q.id)?'1':'2'}
function islandArt(){return `<image href="assets/island-painting-v2.webp" width="600" height="400" preserveAspectRatio="xMidYMid meet"/>`}
function harborArt(){return `<image href="assets/harbor-painting-v2.webp" width="600" height="400" preserveAspectRatio="xMidYMid meet"/>`}
function puzzleSvg(unit,mini=false){const qs=questions.filter(q=>puzzleUnit(q)===unit),cols=12,rows=Math.ceil(qs.length/cols),h=400/rows,prefix=`p${unit}${mini?'m':'f'}`;let tiles='';for(let r=0,idx=0;r<rows;r++){const count=Math.min(cols,qs.length-idx),w=600/count;for(let c=0;c<count;c++,idx++){const q=qs[idx],level=mastery[q.id]?.level||0,x=c*w,y=r*h,clip=`${prefix}-${idx}`,right=x+w,bottom=y+h,k=Math.min(7,w*.15),edge=`M${x} ${y}H${right}V${y+h*.35}${c<count-1?`C${right+k} ${y+h*.35} ${right+k} ${y+h*.65} ${right} ${y+h*.65}`:`L${right} ${y+h*.65}`}V${bottom}H${x}V${y+h*.65}${c>0?`C${x+k} ${y+h*.65} ${x+k} ${y+h*.35} ${x} ${y+h*.35}`:`L${x} ${y+h*.35}`}Z`;tiles+=`<clipPath id="${clip}"><path d="${edge}"/></clipPath><g clip-path="url(#${clip})">${level?`<use href="#${prefix}-art" ${level===1?`filter="url(#${prefix}-gray)"`:''}/>`:`<rect width="600" height="400" fill="#edf0e3" opacity=".86"/>`}</g><path d="${edge}" fill="none" stroke="${level===2?'#ffffff99':'#d0d9c6'}" stroke-width="1.2"/>`}}return `<svg viewBox="0 0 600 400" role="img" aria-label="${PUZZLE_UNITS.find(u=>u.id===unit).title}，灰色為再練習，彩色為我答對了" class="puzzle-svg"><defs><filter id="${prefix}-gray"><feColorMatrix type="saturate" values="0"/></filter><g id="${prefix}-art">${unit==='1'?islandArt():harborArt()}</g></defs><g opacity=".12"><use href="#${prefix}-art"/></g>${tiles}</svg>`}
function puzzleStats(unit){const qs=questions.filter(q=>puzzleUnit(q)===unit);return{total:qs.length,found:qs.filter(q=>(mastery[q.id]?.level||0)>0).length,mastered:qs.filter(q=>mastery[q.id]?.level===2).length}}
let selectedPuzzle='1',previewComplete=false,toastTimer;
function renderPuzzles(){const unit=round&&round.ids[round.index]?puzzleUnit(byId.get(round.ids[round.index])):prefs.unit==='2'?'2':'1',s=puzzleStats(unit);$('puzzleMini').innerHTML=`${puzzleSvg(unit,true)}<span><strong>${PUZZLE_UNITS.find(u=>u.id===unit).title}</strong><small>已發現 ${s.found}/${s.total} · 已上色 ${s.mastered}/${s.total}</small></span><span class="puzzle-open">我的拼圖 →</span>`;$('puzzleMini').dataset.unit=unit;if($('puzzleCollection').open)showPuzzle(selectedPuzzle)}
function showPuzzle(unit){selectedPuzzle=unit;const s=puzzleStats(unit),info=PUZZLE_UNITS.find(u=>u.id===unit);$('puzzleTabs').innerHTML=PUZZLE_UNITS.map(u=>`<button data-puzzle-unit="${u.id}" class="${u.id===unit?'active':''}" aria-pressed="${u.id===unit}">${u.icon} ${u.title}</button>`).join('');$('puzzleArtwork').innerHTML=previewComplete?`<svg viewBox="0 0 600 400" role="img" aria-label="完成圖預覽，不影響學習進度" class="puzzle-svg">${unit==='1'?islandArt():harborArt()}</svg>`:puzzleSvg(unit);$('previewPuzzle').textContent=previewComplete?'返回我的拼圖':'看看完成圖';$('puzzleTitle').textContent=info.title;$('puzzleSubtitle').textContent=info.subtitle;$('puzzleNumbers').textContent=`已發現 ${s.found} / ${s.total} 片　·　已上色 ${s.mastered} / ${s.total} 片`;$('puzzleCompletion').textContent=completedPuzzles[unit]?`🎉 全圖完成！${new Date(completedPuzzles[unit]).toLocaleDateString('zh-TW',{timeZone:'Asia/Taipei'})}`:`再讓 ${s.total-s.mastered} 片變成彩色，就能完成整張圖。`;$('puzzleArtwork').classList.toggle('complete',s.mastered===s.total);$('practicePuzzle').textContent=`練習${unit==='1'?'第一':'第二'}單元 →`}
function openPuzzles(unit){previewComplete=false;showPuzzle(unit);$('puzzleCollection').showModal()}
function notifyPiece(unit,level,completed=false){const box=$('puzzleToast');box.innerHTML=`<span class="piece-pop">🧩</span><span>${completed?'整張拼圖完成了！🎉':level===2?'答對了，一片變彩色！':'灰色拼圖已收下，再接再厲！'}<small>${PUZZLE_UNITS.find(u=>u.id===unit).title}</small></span>`;box.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.hidden=true,2400)}
